// Node 2 -- Validate + format the request for the Salesforce CREATE.
// Form fields are not sf_* named: the ZTree Salesforce package writes sf_* fields as strings and Salesforce rejects
// them for Date/Time/Number fields, so everything goes through Connected Object 505/507 (REST), formatted here.
// Times: Call / Voicemail times are Central (Quest's clock). Time of Incident is saved as entered (local time at the
// event) and Time_of_Incident_Time_Zone__c carries the zone, so nothing is converted.
// Outputs (form data, read by CO 505/507 by ${name}):
//   cr_date_of_incident, cr_call_date (YYYY-MM-DD); cr_time_of_incident, cr_call_time, cr_voicemail_time (HH:MM:SS.000Z);
//   cr_time_zone_sf (Time_of_Incident_Time_Zone__c picklist value); cr_event_state, cr_event_zip, cr_contact_phone,
//   cr_contact_email, cr_number_of_donors, cr_voicemail_received(_bool), cr_specimens, cr_is_valid, cr_create_route;
//   transforms.cr_review_html
function g(k) { return String(ZT.getVariableValue(k, '') || '').trim(); }
function pad2(v) { return ('0' + v).slice(-2); }
function esc(s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function toIsoDate(v) {
  if (!v) return '';
  let m = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/), y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else { m = v.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2}|\d{4})$/); if (!m) return null;
    mo = +m[1]; d = +m[2]; y = m[3].length === 2 ? 2000 + +m[3] : +m[3]; }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  return y + '-' + pad2(mo) + '-' + pad2(d);
}
function toSfTime(v) {
  let m = String(v || '').match(/^(\d{1,2}):([0-5]\d)\s*(AM|PM)$/i);
  if (!m) return null;
  let h = +m[1] % 12 + (m[3].toUpperCase() === 'PM' ? 12 : 0);
  return pad2(h) + ':' + m[2] + ':00.000Z';
}
function showDate(iso) { let m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? m[2] + '/' + m[3] + '/' + m[1] : ''; }
function showTime(sf) {
  let m = String(sf || '').match(/^(\d{2}):(\d{2})/);
  if (!m) return '';
  let h = +m[1];
  return (h % 12 === 0 ? 12 : h % 12) + ':' + m[2] + (h < 12 ? ' AM' : ' PM');
}
function osmEmail(raw) {
  let d = raw.replace(/\D/g, '');
  if (d.length > 6 && d.charAt(0) === '0') d = d.substring(1);
  if (d.length > 6 && d.slice(-2) === '00') d = d.substring(0, d.length - 2);
  return d.length === 6 ? d + '@delta.com' : '';
}
// Salesforce has no Arizona value; Arizona keeps MST all year, so it maps to MST.
const TIME_ZONE_SF = {
  'Eastern (ET)': 'Eastern Standard Time (EST) - 1 hour ahead of CST',
  'Central (CT)': 'Central Standard Time (CST)',
  'Mountain (MT)': 'Mountain Standard Time (MST) - 1 hour behind CST',
  'Arizona (MST)': 'Mountain Standard Time (MST) - 1 hour behind CST',
  'Pacific (PT)': 'Pacific Standard Time (PST) - 2 hours behind CST',
  'Alaska (AKT)': 'Alaska Standard Time (AKST) - 3 hours behind CST',
  'Hawaii (HST)': 'Hawaii Standard Time (HST) - 4 hours behind CST'
};

let errors = [];
let zone = g('req_time_zone');
let zoneSf = TIME_ZONE_SF[zone] || '';
if (!zoneSf) errors.push('Time Zone of Incident is required.');
let date = toIsoDate(g('req_date_of_incident'));
if (!date) errors.push('Date of Incident must be MM/DD/YYYY.');
let time = toSfTime(g('req_time_of_incident'));
if (!time) errors.push('Time of Incident is required.');
let callDate = toIsoDate(g('req_call_date'));
if (!callDate) errors.push('Call Date is required.');
let callTime = toSfTime(g('req_call_time'));
if (!callTime) errors.push('Call Time is required.');
let voicemail = g('req_voicemail_received') === 'Yes' ? 'Yes' : 'No';
let voicemailTime = voicemail === 'Yes' ? toSfTime(g('req_voicemail_time')) : '';
if (voicemail === 'Yes' && !voicemailTime) errors.push('Voicemail Received Time is required when a voicemail was received.');
let specimens = [];
['req_specimen_1', 'req_specimen_2', 'req_specimen_3'].forEach(function (k) {
  let s = g(k); if (s && s !== 'None' && specimens.indexOf(s) === -1) specimens.push(s);
});
if (!specimens.length) errors.push('Select at least one Specimen Requested.');
let state = g('req_event_state').toUpperCase();
if (state && !/^[A-Z]{2}$/.test(state)) errors.push('Event State must be a 2-letter code.');
let zip = g('req_event_zip').replace(/\D/g, '');
if (zip && zip.length !== 5) errors.push('Event Zip must be 5 digits.');
let phone = g('req_contact_phone').replace(/\D/g, '');
let donors = g('req_number_of_donors').replace(/\D/g, '');
let email = osmEmail(g('req_member_id'));

ZT.setFormData('cr_date_of_incident', date || '');
ZT.setFormData('cr_time_of_incident', time || '');
ZT.setFormData('cr_time_zone_sf', zoneSf);
ZT.setFormData('cr_event_state', state);
ZT.setFormData('cr_event_zip', zip);
ZT.setFormData('cr_contact_phone', phone);
ZT.setFormData('cr_contact_email', email);
ZT.setFormData('cr_number_of_donors', donors || '1');
ZT.setFormData('cr_call_date', callDate || '');
ZT.setFormData('cr_call_time', callTime || '');
ZT.setFormData('cr_voicemail_received', voicemail);
ZT.setFormData('cr_voicemail_received_bool', voicemail === 'Yes' ? 'true' : 'false');
ZT.setFormData('cr_voicemail_time', voicemailTime || '');
ZT.setFormData('cr_specimens', specimens.join(';'));
ZT.setFormData('cr_is_valid', errors.length ? 'false' : 'true');
// SF rejects a blank Time value, so Voicemail = No creates through CO 507 (no Voicemail_Received_Time__c).
ZT.setFormData('cr_create_route', errors.length ? 'invalid' : (voicemail === 'Yes' ? 'vm' : 'novm'));

function row(l, v) { return '<tr><td style="padding:6px 10px;font-weight:700;color:#374151;width:210px;">' + esc(l) + '</td><td style="padding:6px 10px;color:#111827;">' + esc(v || '-') + '</td></tr>'; }
function section(title, rows) {
  return '<div style="font-weight:800;color:#12395b;margin:14px 0 4px;">' + esc(title) + '</div>'
    + '<table style="border-collapse:collapse;width:100%;border:1px solid #e5e7eb;">' + rows + '</table>';
}
let html = '<div style="font-family:Arial,sans-serif;max-width:760px;">';
if (errors.length) html += '<div style="border:1px solid #fecaca;background:#fef2f2;border-radius:12px;padding:12px;margin-bottom:10px;"><div style="font-weight:800;color:#991b1b;">Fix before submitting</div><div style="color:#374151;">' + errors.map(esc).join('<br>') + '</div></div>';
html += section('Collection Information',
    row('Event Type', g('req_event_type'))
  + row('Call Date', showDate(callDate)) + row('Call Time', callTime ? showTime(callTime) + ' Central' : '')
  + row('Voicemail Received', voicemail + (voicemailTime ? ' at ' + showTime(voicemailTime) + ' Central' : ''))
  + row('Date of Incident', showDate(date)) + row('Time of Incident', time ? showTime(time) + ' ' + zone : ''))
  + section('Onsite Information',
    row('Airport Code', g('req_airport_code'))
  + row('Event Address', [g('req_event_address'), g('req_event_city'), state, zip].filter(Boolean).join(', '))
  + row('Contact Name', g('req_contact_name')) + row('Contact Phone', phone)
  + row('Contact ID Number', g('req_member_id')) + row('Contact Email', email)
  + row('Contact Job Title', g('req_supervisor_job_title')) + row('Contact Department Number', g('req_supervisor_department_number'))
  + row('Number of Donors', donors || '1'))
  + section('Donor Information',
    row('Donor Name', g('req_donor_name')) + row('Donor ID', g('req_donor_id'))
  + row('Donor Job Title', g('req_donor_job_title')) + row('Donor Department Number', g('req_donor_department_number'))
  + row('Flight #', g('req_flight')) + row('Ship #', g('req_ship')) + row('Vehicle #', g('req_vehicle'))
  + row('Specimens Requested', specimens.join(', ')))
  + section('Notes', row('Notes', g('req_notes')))
  + '</div>';
ZT.setTransformData('cr_review_html', html);

