// Node 5 -- Read the Salesforce CREATE result (Connected Object 505, alias create_sf_event_request)
// CO 505 schema preview (2026-10-15): { response: { code, data: { success, id?, errors: [{ fields, message, errorCode }] } } }
// Outputs: cr_created ('true'/'false'), cr_record_id, transforms.cr_result_html
// CR-003: Voicemail = No creates through CO 507 (alias create_sf_event_request_novm).
var acts = (typeof actions !== 'undefined' && actions) || {};
var res = (String(ZT.getVariableValue('cr_create_route', '')) === 'novm' ? acts.create_sf_event_request_novm : acts.create_sf_event_request) || {};
var resp = res.response || res;
var data = resp.data || res.data || (res.value && res.value[0]) || res;
var code = resp.code || (res._zt_meta && res._zt_meta.response && res._zt_meta.response.code) || 0;
var id = data.id || data.Id || res.id || '';
var meta = (res._zt_meta && res._zt_meta.response) || {};
var errs = data.errors || res.errors || (Array.isArray(meta.body) ? meta.body : (meta.body && meta.body.errors) || []);  // 4xx: SF error array lands in _zt_meta.response.body
var ok = !!id && data.success !== false && (!code || (code >= 200 && code < 300));
ZT.setFormData('cr_created', ok ? 'true' : 'false');
ZT.setFormData('cr_record_id', id);
var errText = errs.map(function (e) { return (e.errorCode ? e.errorCode + ': ' : '') + (e.message || '') + (e.fields && e.fields.length ? ' (' + e.fields.join(', ') + ')' : ''); }).join(' | ');
var msg = ok ? 'ES Event Request created. Salesforce ID: ' + id
  : 'Salesforce did not create the record' + (code ? ' (HTTP ' + code + ')' : '') + '. ' + (errText || 'No error detail returned.');
// Quest UAT sandbox org; the production org has a different host (remap on promotion).
var sfRecordUrl = 'https://ies-questdiagnostics--zingtree.sandbox.lightning.force.com/lightning/r/ES_Event_Request__c/' + id + '/view';
ZT.setFormData('cr_record_url', ok ? sfRecordUrl : '');
var openButton = ok
  ? '<div style="margin-top:12px;"><a href="' + sfRecordUrl + '" target="_blank" rel="noopener noreferrer" style="display:inline-block;background:#2457c5;color:#ffffff;text-decoration:none;font-weight:800;padding:10px 16px;border-radius:10px;">Open Event in Salesforce</a></div>'
  : '';
ZT.setTransformData('cr_result_html', '<div style="font-family:Arial,sans-serif;border:1px solid ' + (ok ? '#c7d2fe;background:#eef2ff' : '#fecaca;background:#fef2f2') + ';border-radius:12px;padding:12px;">' + msg.replace(/</g, '&lt;') + openButton + '</div>');
